 FOR UPDATE OF p
), audited AS (
 INSERT INTO pp_amaga_attachment_recovery_20261101(publicacion_id,remote_url,publication_before,native_article_id,native_asset_id)
 SELECT publicacion_id,remote_url,publication_before,article_id,asset_id FROM eligible
 ON CONFLICT DO NOTHING RETURNING publicacion_id,remote_url
), enqueued AS (
 INSERT INTO estado_attachment_queue(work_item_id,publicacion_id,organization_id,remote_url,filename,status,attempt_count,max_attempts,next_retry_at)
 SELECT e.work_item_id,e.publicacion_id,e.organization_id,e.remote_url,e.filename,'pending',0,5,now()
 FROM eligible e JOIN audited a USING(publicacion_id,remote_url)
 ON CONFLICT(publicacion_id,remote_url) DO NOTHING RETURNING id,publicacion_id
)
SELECT count(*) AS new_associations,count(DISTINCT publicacion_id) AS publications FROM enqueued;
